#!/usr/bin/env node
// Generates src/lib/api/schema.d.ts from the Nexus management API contract.
//
//   pnpm api:types                 # fetch $NEXUS_API_URL/openapi.json, refresh the snapshot, regenerate
//   pnpm api:types --from-snapshot # regenerate from openapi/openapi.json without a running API
//   pnpm api:types --check         # fail if the generated file differs from the snapshot output
//
// The snapshot (openapi/openapi.json) and the generated types are both committed so that
// CI and contributors can build without a running API.
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const snapshotPath = resolve(root, "openapi/openapi.json");
const outputPath = resolve(root, "src/lib/api/schema.d.ts");
const args = new Set(process.argv.slice(2));
const check = args.has("--check");
const fromSnapshot = check || args.has("--from-snapshot");

async function loadContract() {
  if (fromSnapshot) {
    return JSON.parse(await readFile(snapshotPath, "utf8"));
  }
  const base = (process.env.NEXUS_API_URL ?? "http://127.0.0.1:8000").replace(/\/+$/, "");
  const response = await fetch(`${base}/openapi.json`, { headers: { accept: "application/json" } });
  if (!response.ok) {
    throw new Error(
      `GET ${base}/openapi.json returned ${response.status}. Start the API in development mode ` +
        "(the endpoint is disabled in production) or use --from-snapshot.",
    );
  }
  const contract = await response.json();
  await mkdir(dirname(snapshotPath), { recursive: true });
  await writeFile(snapshotPath, `${JSON.stringify(contract, null, 2)}\n`);
  return contract;
}

const contract = await loadContract();
const ast = await openapiTS(contract, {
  alphabetize: true,
  exportType: true,
  rootTypes: false,
});
const header =
  "// Generated by scripts/generate-api-types.mjs from openapi/openapi.json. Do not edit by hand.\n" +
  `// Contract: ${contract.info?.title ?? "Nexus"} ${contract.info?.version ?? ""}\n\n`;
const output = header + astToString(ast);

if (check) {
  const current = await readFile(outputPath, "utf8").catch(() => "");
  if (current !== output) {
    console.error("src/lib/api/schema.d.ts is out of date. Run `pnpm api:types --from-snapshot`.");
    process.exit(1);
  }
  console.log("API types match openapi/openapi.json.");
} else {
  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, output);
  console.log(`Wrote ${outputPath}`);
}
